//! IPC protocol v1 between `pilas-hook` and the app: one JSON line per message.

use serde::{Deserialize, Serialize};
use serde_json::Value;

pub const PROTOCOL_VERSION: u32 = 1;
pub const AGENT_CLAUDE_CODE: &str = "claude-code";

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct HookMessage {
    pub v: u32,
    /// UUID generated by the hook; the reply must carry the same one.
    pub id: String,
    /// Always `claude-code` in v1; extension point for other agents.
    pub agent: String,
    pub event: String,
    pub blocking: bool,
    #[serde(default)]
    pub tty: Option<String>,
    #[serde(default)]
    pub pid: Option<u32>,
    #[serde(default)]
    pub term_program: Option<String>,
    /// Claude Code's original JSON, unmodified.
    pub payload: Value,
}

/// Only sent for blocking events.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AppReply {
    pub v: u32,
    pub id: String,
    /// Printed verbatim by the hook. `None` means no decision (answer in the terminal).
    pub stdout: Option<Value>,
}

impl AppReply {
    pub fn new(id: impl Into<String>, stdout: Option<Value>) -> Self {
        Self {
            v: PROTOCOL_VERSION,
            id: id.into(),
            stdout,
        }
    }
}

pub fn tool_name(payload: &Value) -> Option<&str> {
    payload.get("tool_name")?.as_str()
}

pub fn session_id(payload: &Value) -> Option<&str> {
    payload.get("session_id")?.as_str()
}

/// - `PermissionRequest` blocks, except for `AskUserQuestion`: Claude Code also fires
///   `PermissionRequest` for that tool and it must be ignored so the card is not duplicated.
/// - `PreToolUse` blocks only for `AskUserQuestion` (answers go through `updatedInput`).
pub fn is_blocking(event: &str, payload: &Value) -> bool {
    match event {
        "PermissionRequest" => tool_name(payload) != Some("AskUserQuestion"),
        "PreToolUse" => tool_name(payload) == Some("AskUserQuestion"),
        _ => false,
    }
}

pub fn is_ignored(event: &str, payload: &Value) -> bool {
    event == "PermissionRequest" && tool_name(payload) == Some("AskUserQuestion")
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    #[test]
    fn blocking_events() {
        assert!(is_blocking("PermissionRequest", &json!({"tool_name": "Bash"})));
        assert!(!is_blocking(
            "PermissionRequest",
            &json!({"tool_name": "AskUserQuestion"})
        ));
        assert!(is_blocking("PreToolUse", &json!({"tool_name": "AskUserQuestion"})));
        assert!(!is_blocking("PreToolUse", &json!({"tool_name": "Edit"})));
        assert!(!is_blocking("Stop", &json!({})));
    }

    #[test]
    fn ignores_permission_request_for_questions() {
        assert!(is_ignored(
            "PermissionRequest",
            &json!({"tool_name": "AskUserQuestion"})
        ));
        assert!(!is_ignored("PermissionRequest", &json!({"tool_name": "Bash"})));
    }

    #[test]
    fn json_round_trip() {
        let m = HookMessage {
            v: PROTOCOL_VERSION,
            id: "abc".into(),
            agent: AGENT_CLAUDE_CODE.into(),
            event: "Stop".into(),
            blocking: false,
            tty: Some("/dev/ttys004".into()),
            pid: Some(42),
            term_program: Some("ghostty".into()),
            payload: json!({"session_id": "s1"}),
        };
        let line = serde_json::to_string(&m).unwrap();
        assert_eq!(serde_json::from_str::<HookMessage>(&line).unwrap(), m);
    }
}
